def create_optimize_inputs_from_log(log_path):
    """
    Parse the latest 'Pollux optimize inputs' block from a log file and
    reconstruct (jobs, nodes, base_allocations, node_template) suitable
    for PolluxPolicy.optimize(...).

    Returns:
        jobs_dict (dict): {(namespace, name): JobInfo}
        nodes_dict (dict): {node_name: NodeInfo}
        base_allocations (dict): {(namespace, name): [node_name, ...]}
        node_template (NodeInfo)
    """
    import ast
    import re
    from datetime import datetime

    # Lightweight containers compatible with PolluxPolicy expectations
    class _JobInfo:
        def __init__(self, resources, creation_timestamp, min_replicas, max_replicas,
                     preemptible=True, application=None, epoch=None):
            self.resources = resources
            self.creation_timestamp = creation_timestamp
            self.min_replicas = min_replicas
            self.max_replicas = max_replicas
            self.preemptible = preemptible
            self.application = application
            self.epoch = epoch

    class _NodeInfo:
        def __init__(self, resources, preemptible):
            self.resources = resources
            self.preemptible = preemptible

    def _parse_literal_dict(text_after_equals):
        # The log uses Python-style dicts with single quotes; ast.literal_eval handles this.
        return ast.literal_eval(text_after_equals.strip())

    def _to_job_key(key_str):
        # Keys look like "('adaptdl', 'cifar10-0')"; convert to tuple.
        try:
            key = ast.literal_eval(key_str)
            return key if isinstance(key, tuple) else key
        except Exception:
            return key_str

    # Read log and find latest four lines for jobs/nodes/base_allocations/node_template
    with open(log_path, 'r') as f:
        lines = f.readlines()

    latest = {
        'jobs': None,
        'nodes': None,
        'base_allocations': None,
        'node_template': None,
    }

    pattern_map = {
        'jobs': re.compile(r"Pollux optimize inputs \| jobs=(.*)$"),
        'nodes': re.compile(r"Pollux optimize inputs \| nodes=(.*)$"),
        'base_allocations': re.compile(r"Pollux optimize inputs \| base_allocations=(.*)$"),
        'node_template': re.compile(r"Pollux optimize inputs \| node_template=(.*)$"),
    }

    # Scan from bottom to top and capture the first full set we encounter
    found = set()
    for line in reversed(lines):
        for key, pat in pattern_map.items():
            m = pat.search(line)
            if m and latest[key] is None:
                latest[key] = _parse_literal_dict(m.group(1))
                found.add(key)
        if len(found) == 4:
            break

    if len(found) < 4:
        raise ValueError("Could not find a complete 'Pollux optimize inputs' block in log")

    # Reconstruct nodes
    nodes_dict = {}
    for node_name, node_data in latest['nodes'].items():
        resources = dict(node_data.get('resources', {}))
        preemptible = bool(node_data.get('preemptible', False))
        nodes_dict[node_name] = _NodeInfo(resources=resources, preemptible=preemptible)

    # Reconstruct node_template
    nt = latest['node_template']
    node_template = _NodeInfo(resources=dict(nt.get('resources', {})),
                              preemptible=bool(nt.get('preemptible', True)))

    # Reconstruct base_allocations
    base_allocations = {}
    for k_str, alloc_list in latest['base_allocations'].items():
        base_allocations[_to_job_key(k_str)] = list(alloc_list)

    # Reconstruct jobs
    jobs_dict = {}
    for k_str, info in latest['jobs'].items():
        key = _to_job_key(k_str)
        resources = dict(info.get('resources', {}))
        min_replicas = int(info.get('min_replicas', 0))
        max_replicas = int(info.get('max_replicas', 1))
        preemptible = bool(info.get('preemptible', True))
        application = info.get('application')
        epoch = info.get('epoch')
        # Parse ISO timestamp if present; fall back to 0
        ts = info.get('creation_timestamp')
        if isinstance(ts, str):
            try:
                creation_timestamp = datetime.fromisoformat(ts.replace('Z', '+00:00')).timestamp()
            except Exception:
                creation_timestamp = 0
        else:
            creation_timestamp = 0
        jobs_dict[key] = _JobInfo(resources=resources,
                                  creation_timestamp=creation_timestamp,
                                  min_replicas=min_replicas,
                                  max_replicas=max_replicas,
                                  preemptible=preemptible,
                                  application=application,
                                  epoch=epoch)

    return jobs_dict, nodes_dict, base_allocations, node_template


